export const words: Word[] = [
  { word: "Abatatado", meaning: "Avergonzado o asustado; que perdió la compostura ante una situación incómoda.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, donde figura como participio de «abatatarse». El término se conserva hasta hoy con el mismo sentido de perder el aplomo por miedo o vergüenza.", example: "Quedó abatatado apenas el comisario le hizo la primera pregunta." },
  { word: "Abatatarse", meaning: "Avergonzarse o asustarse, perder la seguridad ante una situación incómoda.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado. Dellepiane ya la registra como verbo de uso corriente entre los delincuentes porteños de fin del siglo XIX.", example: "No te abatatés y contestá tranquilo." },
  { word: "Abiabar", meaning: "Herir a golpes; dar una paliza.", category: "tumbero", origin: "Registrada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. El propio Dellepiane la remite directamente a «biaba» (herida, golpiza), de donde deriva el verbo.", example: "Lo abiabaron entre dos apenas salió del boliche." },
  { word: "Acordinada", meaning: "La mujer o compañera de un ladrón.", category: "tumbero", origin: "Aparece desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo jamás publicado. El texto la define en relación directa con «choro» (ladrón), como la pareja de un hombre dedicado al robo.", example: "La acordinada lo esperaba todas las noches en la esquina." },
  { word: "Acordinado", meaning: "Casado, unido en pareja.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como participio de «acordinarse» (casarse).", example: "Ya está acordinado hace dos años con la Rosa." },
  { word: "Acordinarse", meaning: "Casarse, unirse en pareja.", category: "bajofondo", origin: "Figura desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado. Es la forma reflexiva de la que derivan «acordinado» y «acordinada».", example: "Dicen que se van a acordinar apenas junten unos pesos." },
  { word: "Afanador", meaning: "Ladrón, el que roba o estafa.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, primer diccionario de lunfardo publicado, donde figura como sinónimo de estafador. Con el tiempo, «afanar» se generalizó como el verbo más popular para nombrar el robo en el habla rioplatense.", example: "Lo agarraron como afanador de carteras en la estación." },
  { word: "Afanar", meaning: "Robar, estafar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Es una de las voces lunfardas que más se popularizó, hasta transformarse en sinónimo cotidiano de robar en todo el Río de la Plata.", example: "Le afanaron la bicicleta que había dejado en la vereda." },
  { word: "Al bombo", meaning: "Morirse; mandar al bombo a alguien es matarlo.", category: "tumbero", origin: "Registrada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado, como locución para nombrar la muerte violenta dentro del ambiente delictivo.", example: "Amenazó con mandarlo al bombo si volvía a delatarlo." },
  { word: "Alicante", meaning: "Peine.", category: "bajofondo", origin: "Aparece desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como parte del vocabulario cifrado que los ladrones usaban para nombrar objetos cotidianos.", example: "Guardaba el alicante en el bolsillo de atrás." },
  { word: "Altura", meaning: "En la jerga de los especialistas en llaves, la medida de una llave: el largo de la paleta más el diámetro de la caña.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado, dentro del vocabulario técnico que usaban quienes fabricaban o copiaban llaves para robar.", example: "El cerrajero del gremio le tomó la altura para hacerle una copia." },
  { word: "Alumbrante", meaning: "Vela.", category: "bajofondo", origin: "Registrada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en clave para un objeto de uso corriente entre los ladrones nocturnos.", example: "Encendió el alumbrante antes de entrar a la pieza a oscuras." },
  { word: "Amarillo", meaning: "Oro; también se usaba para nombrar el dinero o el coñac.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. El texto anota que también se lo llamaba «como pulenta» o «como pájaro cantador», otras metáforas lunfardas para el oro.", example: "Le sacó todo el amarillo que tenía en la caja fuerte." },
  { word: "Amendrar", meaning: "Tardar, demorarse.", category: "cotidiano", origin: "Aparece desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, entre las voces de uso general del habla porteña de la época.", example: "No amendrés que el tren ya está por salir." },
  { word: "Amurado", meaning: "Preso, encarcelado.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «encanado», «apanado» y «estarado». Todas nombraban lo mismo: estar privado de la libertad.", example: "Quedó amurado tres años por aquel robo." },
  { word: "Amurar", meaning: "Empeñar algo como garantía de un préstamo; también encerrar o aprisionar.", category: "tumbero", origin: "Registrada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado, con un doble sentido: dejar algo en prenda y, por extensión, encerrar a una persona.", example: "Tuvo que amurar el reloj para pagar el alquiler." },
  { word: "Ancón", meaning: "Cuidado, precaución ante un peligro inminente.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Se usaba como advertencia entre ladrones, por ejemplo en la frase «ancón, que hay cana», para alertar sobre la presencia de la policía.", example: "¡Ancón!, gritó el campana al ver acercarse al vigilante." },
  { word: "Apanado", meaning: "Preso, detenido.", category: "tumbero", origin: "Figura desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como participio de «apanar» (atacar) y sinónimo de «amurado», «encanado» y «estarado».", example: "Cayó apanado la misma noche del robo." },
  { word: "Apanar", meaning: "Atacar a alguien.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como verbo del que deriva «apanado» (preso, atrapado tras el ataque).", example: "Lo apanaron entre tres a la salida del boliche." },
  { word: "Aro", meaning: "En la jerga de los ladrones de llaves, el anillo de la llave.", category: "tumbero", origin: "Registrada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado, dentro del glosario técnico sobre las partes de una llave que usaban los especialistas en robos con llave falsa.", example: "Le faltaba el aro a la llave que encontraron en la escena." },
  { word: "Arzobispo", meaning: "Cortafierro, herramienta para forzar cerraduras o rejas.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo humorístico de «santo» y «corte», otros nombres en clave para la misma herramienta.", example: "Entraron con el arzobispo y forzaron la reja del fondo." },
  { word: "Atorradero", meaning: "Lugar donde se duerme o se pasa la noche, especialmente si es precario.", category: "bajofondo", origin: "Aparece desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «atorro» y «atorrar» (dormir).", example: "Encontró un atorradero bajo el puente para pasar la noche." },
  { word: "Atorrante", meaning: "Persona vaga, ociosa, sin oficio fijo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, donde se la define como sinónimo de «reo» y se la vincula con «atorrar» (dormir). Con el tiempo se convirtió en una de las palabras lunfardas más difundidas del español rioplatense.", example: "Dejate de hacerte el atorrante y buscate un laburo." },
  { word: "Atorrar", meaning: "Dormir.", category: "bajofondo", origin: "Registrada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como raíz de «atorrante» y «atorro». Todavía se usa hoy en el habla coloquial con el mismo sentido.", example: "Después del asado me fui a atorrar toda la siesta." },
  { word: "Atorro", meaning: "Acción de dormir; también el hecho de vivir sin trabajo fijo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, definida allí como la acción y efecto de «atorrar».", example: "Se tomó el día para el atorro después de trabajar toda la semana." },
  { word: "Bacana", meaning: "Mujer de dinero o buena posición; también la mujer que mantiene o protege a alguien.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como femenino de «bacán». Se vincula con el genovés «baccan» (patrón, jefe de familia), voz traída por la inmigración italiana.", example: "Se paseaba del brazo de la bacana más elegante del barrio." },
  { word: "Bacán", meaning: "Hombre adinerado o de buena posición; patrón o protector de alguien.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, con varias acepciones según el contexto: dueño de una casa, patrón de un local o simplemente hombre de plata. Se relaciona con el genovés «baccan» (jefe de familia), término llegado con la inmigración italiana.", example: "Se hacía el bacán aunque apenas le alcanzaba para el tranvía." },
  { word: "Bagayo", meaning: "Mercadería o bulto de ropa y objetos, en general robados.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Con el tiempo el término amplió su uso y hoy también se aplica, en tono despectivo, a una persona de aspecto poco agraciado.", example: "Escondieron el bagayo en el fondo de la casa hasta poder venderlo." },
  { word: "Balurdo", meaning: "Rollo de papeles que, a primera vista, parece un fajo de dinero, usado para engañar a la víctima en una estafa.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como herramienta central del «trabajo de cuento», una de las estafas clásicas descriptas en el libro.", example: "Le mostró el balurdo para convencerlo de que la plata era real." },
  { word: "Baqueana", meaning: "Botella de licor.", category: "bajofondo", origin: "Registrada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en código para un objeto de consumo habitual en los ambientes que describe el libro.", example: "Compartieron una baqueana de caña entre los tres." },
  { word: "Baratinar", meaning: "En el cuento del tío, cambiar el fajo falso por el dinero verdadero de la víctima sin que esta lo note.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «pegar el cambiazo», la maniobra central del trabajo de cuento.", example: "El estafador logró baratinar al otario sin que este sospechara nada." },
  { word: "Baratín", meaning: "El rollo de papel de estraza que se le deja a la víctima a cambio de su dinero verdadero, en la estafa del cuento.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como el objeto falso que se intercambiaba en el «trabajo de cuento», la estafa clásica de la época.", example: "Cuando abrió el paquete solo encontró el baratín." },
  { word: "Barbusa", meaning: "Barba o patilla.", category: "bajofondo", origin: "Registrada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para el vello facial.", example: "Se dejó crecer la barbusa para no ser reconocido." },
  { word: "Batida", meaning: "Declaración o confesión; una batida sucia es una mala acción.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «batir» (decir, declarar, denunciar).", example: "Hizo la batida completa apenas lo interrogó el comisario." },
  { word: "Batidor", meaning: "Denunciante; el que delata a sus cómplices ante la policía.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es una de las figuras más despreciadas dentro del código del ambiente delictivo que retrata el libro.", example: "Lo marcaron como batidor y nadie más le habló." },
  { word: "Batifondio", meaning: "Gresca, alboroto, desorden.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, emparentada con «batuque», otra voz lunfarda para nombrar el barullo.", example: "Se armó un batifondio cuando llegó la policía al boliche." },
  { word: "Batimento", meaning: "Conversación, declaración o afirmación.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro de la familia de palabras derivadas de «batir» (hablar, declarar).", example: "Tuvieron un largo batimento antes de ponerse de acuerdo." },
  { word: "Batir", meaning: "Decir, contar o declarar algo; también denunciar o delatar a alguien.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con expresiones como «batir la cana» (delatar a los cómplices) o «batir el justo» (confesar la verdad).", example: "No pensaba batir nada aunque lo interrogaran toda la noche." },
  { word: "Batuque", meaning: "Desorden, barullo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «batifondio».", example: "Armaron tremendo batuque en la puerta del boliche." },
  { word: "Biaba", meaning: "Golpe o herida; también un asalto violento.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. El libro distingue una «biaba seca» (que termina en muerte) del simple golpe, y de ella derivan «abiabar» y «biabista».", example: "Le dieron una biaba tremenda por no pagar la deuda." },
  { word: "Biabista", meaning: "Ladrón que roba mediante el asalto y la violencia.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «biaba» (golpe), la marca distintiva de este tipo de ladrón.", example: "Los biabistas de la zona actuaban siempre de noche y en pareja." },
  { word: "Blanca", meaning: "Dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, una de las tantas voces que la jerga delictiva usaba para nombrar la plata.", example: "No le quedaba ni una blanca después de la timba." },
  { word: "Bobera", meaning: "Relojería, el local donde se venden o arreglan relojes.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «bobo» (reloj), dentro de un vocabulario especializado para el robo de relojes.", example: "Vendió los relojes robados a un conocido que atendía una bobera." },
  { word: "Bobo", meaning: "Reloj. Un bobo garroteado es aquel al que le falta el anillo, y el bobo andante es la cadena del reloj.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro de todo un vocabulario específico dedicado al robo de relojes, muy común en la delincuencia urbana de la época.", example: "Le hizo un bobo al pasajero mientras esperaban el tranvía." },
  { word: "Bolacha", meaning: "Galleta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para un alimento de consumo diario.", example: "Compró unas bolachas para comer en el viaje." },
  { word: "Boliche", meaning: "Almacén o despacho de bebidas.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. La palabra sobrevivió con fuerza y hoy nombra, en general, cualquier bar o local nocturno.", example: "Se juntaban todas las noches en el boliche de la esquina." },
  { word: "Bolichero", meaning: "Dueño o encargado de un almacén.", category: "cotidiano", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada directamente de «boliche».", example: "El bolichero le fiaba la mercadería a fin de mes." },
  { word: "Bomba", meaning: "Cierto tipo de llave usada para forzar cerraduras. Una bomba de mano es una piedra.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario técnico de los especialistas en robos con llaves falsas.", example: "Usó la bomba para forzar la cerradura del depósito." },
  { word: "Bora", meaning: "Libertad. Salir en bora es salir en libertad.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario carcelario que describe el paso de la prisión a la libertad.", example: "Salió en bora después de cumplir toda la condena." },
  { word: "Botón", meaning: "Vigilante o agente de policía.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «chafo» o «chaffe». «Botón» se mantiene hasta hoy como una de las formas más comunes para nombrar a un policía.", example: "Apareció un botón justo cuando estaban por entrar." },
  { word: "Brema", meaning: "Baraja de naipes; una brema floreada o jamada es una baraja marcada para hacer trampa.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario de los tahúres que marcaban los naipes para asegurarse la ganancia.", example: "Descubrieron que jugaba con una brema floreada." },
  { word: "Brija", meaning: "Cadena de reloj.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «traya» y «marroca», otros nombres en jerga para la misma pieza, muy buscada por los ladrones de relojes.", example: "Le arrancó la brija de un tirón sin que se diera cuenta." },
  { word: "Brillo", meaning: "Diamante o piedra preciosa.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como abreviación de «brillante».", example: "Llevaba un brillo enorme en el anillo." },
  { word: "Bufarrón", meaning: "Hombre que ejerce el rol activo en una relación homosexual, en el vocabulario de la época.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario que el libro dedica a los roles y relaciones del ambiente carcelario y delictivo del siglo XIX.", example: "Le decían bufarrón por su fama en el pabellón." },
  { word: "Bufón", meaning: "Arma de fuego, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «bufosa».", example: "Sacó el bufón apenas vio entrar a los policías." },
  { word: "Bufosa", meaning: "Arma de fuego. Una bufosa corta es una pistola o revólver; una bufosa larga es un rifle o una escopeta.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «bufón», distinguiendo entre armas cortas y largas.", example: "Guardaba la bufosa escondida bajo el colchón." },
  { word: "Bullón", meaning: "Sopa.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, de la que deriva el verbo «bullonar» (comer).", example: "Se tomó todo el bullón antes de salir a la calle." },
  { word: "Bullonar", meaning: "Comer.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «bullón» (sopa).", example: "Bullonaron rápido antes de salir a trabajar." },
  { word: "Bulín", meaning: "Habitación o vivienda de soltero. Un bulín grande es una casa, y el bacán de bulín es el dueño o casero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Es una de las voces lunfardas que más perduró y que el tango inmortalizó como sinónimo de morada íntima.", example: "Se juntaban todas las noches en el bulín de la esquina." },
  { word: "Burra de viaje", meaning: "Baúl. Una burrita de viaje es una maleta más chica.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para el equipaje que solía ser objeto de robo en estaciones y puertos.", example: "Dejó la burra de viaje en la consigna de la estación." },
  { word: "Burrita", meaning: "Maleta pequeña de viaje.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como diminutivo de «burra de viaje».", example: "Cargaba solo una burrita con lo justo para el fin de semana." },
  { word: "Burro", meaning: "Cajón de un mostrador o de un escritorio. Un burro coceador es el que tiene campanilla de alarma.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico de los ladrones que se especializaban en forzar cajones y mostradores.", example: "Forzó el burro del mostrador sin hacer ruido." },
  { word: "Busarda", meaning: "Boca. Poner la caramayola en la busarda es tapar la boca con un pañuelo al momento de asaltar a alguien.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro de la descripción de las técnicas de asalto con acogotamiento que describe el libro.", example: "Le taparon la busarda antes de que pudiera gritar." },
  { word: "Cabalete", meaning: "Bolsillo del traje, en sentido general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario específico de los punguistas (ladrones de bolsillo).", example: "Le vació el cabalete sin que se diera cuenta." },
  { word: "Cabrear", meaning: "Recelar, desconfiar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, de la que deriva «cabrero». El sentido moderno de «enojarse» es una evolución posterior de esta misma raíz.", example: "Empezó a cabrear cuando le hicieron tantas preguntas." },
  { word: "Cabrero", meaning: "Hombre receloso, desconfiado, difícil de engañar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como adjetivo derivado de «cabrear».", example: "Con un tipo tan cabrero, el cuento del tío no iba a funcionar." },
  { word: "Caco", meaning: "Ladrón, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «ladrillo», «lunfardo», «lunfa», «choro» y «malevo». El nombre remite al mítico ladrón Caco de la mitología romana.", example: "Lo agarraron con las manos en la masa, como un caco cualquiera." },
  { word: "Cada", meaning: "La entrada a la prisión.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario carcelario del libro.", example: "Cruzó la cada esposado entre dos vigilantes." },
  { word: "Cala", meaning: "Carruaje.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un medio de transporte de la época.", example: "Escaparon en una cala apenas sonó la alarma." },
  { word: "Calote", meaning: "La acción de irse sin pagar lo consumido. Dar o pegar un calote es justamente eso.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, de la que derivan «calotear» y «caloteador». El término se mantiene vigente hoy con el mismo sentido.", example: "Le pegaron un calote al dueño del boliche y se fueron corriendo." },
  { word: "Caloteador", meaning: "El que se va sin pagar lo que consumió.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «calote».", example: "Era conocido como caloteador en todos los boliches del barrio." },
  { word: "Calotear", meaning: "Irse sin pagar lo que se ha consumido.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «calote» y «caloteador».", example: "Calotearon la cena y salieron corriendo por la puerta de atrás." },
  { word: "Cambial", meaning: "Letra de cambio.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un documento financiero habitual entre estafadores.", example: "Falsificó un cambial para cobrar una plata que no le correspondía." },
  { word: "Cambiaso", meaning: "Cambio; el acto de cambiar. Pegar el cambiaso es lo mismo que baratinar: sustituir el dinero verdadero de la víctima por uno falso.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro de la descripción del trabajo de cuento.", example: "Le pegaron el cambiaso sin que se diera cuenta hasta llegar a su casa." },
  { word: "Caminante", meaning: "Zapato o calzado. Un caminante de tela es una alpargata.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «fangushe».", example: "Se compró unos caminantes nuevos para el domingo." },
  { word: "Caminar", meaning: "Robar en compañía de otro, bajo sus órdenes.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, con el sentido específico de trabajar en pareja o banda dentro del oficio del robo.", example: "Hacía años que caminaba con la misma banda." },
  { word: "Camisulón", meaning: "Chaleco.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para una prenda de vestir.", example: "Guardaba la navaja en el bolsillo del camisulón." },
  { word: "Campana", meaning: "El ayudante que vigila o sigue a alguien para dar la alarma mientras otros efectúan el robo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es una de las voces lunfardas más conocidas y todavía se usa hoy para nombrar al que avisa de un peligro.", example: "Puso a un pibe de campana en la esquina mientras entraban." },
  { word: "Campaneadero", meaning: "Lugar desde donde se atisba o vigila.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «campanear» (mirar, atisbar).", example: "Eligió la terraza como campaneadero para controlar la cuadra." },
  { word: "Campanear", meaning: "Mirar, vigilar con disimulo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «campana» y «campaneadero». Hoy se sigue usando con el sentido de observar algo de reojo.", example: "Lo campaneaba desde la vereda de enfrente sin que se diera cuenta." },
  { word: "Cana", meaning: "En la jerga de los ladrones de llaves, la pieza que va desde el aro hasta la paleta.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico sobre las partes de una llave. Curiosamente, el mismo libro usa «cana» en otras entradas con el sentido de policía o peligro (como en «ancón, que hay cana»), el uso que terminó imponiéndose y que hoy es el único vigente.", example: "Le faltaba un pedazo de cana a la llave maestra." },
  { word: "Canfinfle", meaning: "Hombre que vive a costa de una mujer que ejerce la prostitución.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario que el libro dedica al mundo de la prostitución porteña de fines del siglo XIX.", example: "Todos en la cuadra sabían que era un canfinfle." },
  { word: "Canoa", meaning: "Pie.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «pisante».", example: "Tenía las canoas destrozadas después de tanto caminar." },
  { word: "Canon", meaning: "Caña, bebida alcohólica; también aguardiente.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para una bebida de consumo habitual en los ambientes que retrata el libro.", example: "Pidió un canon para entrar en calor." },
  { word: "Caramayola", meaning: "Pelota hecha con un pañuelo que se introducía en la boca de una persona para impedir que gritara durante un asalto.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro de la descripción de las técnicas del llamado «trabajo de caramayola», el asalto con acogotamiento.", example: "Le pusieron la caramayola antes de llevarse todo lo de valor." },
  { word: "Cascabel", meaning: "La pequeña virola que suelen tener las llaves cerca del aro.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del glosario técnico sobre llaves que usaban los especialistas en robos con llave falsa.", example: "Reconoció la llave por el cascabel gastado." },
  { word: "Catar", meaning: "Sacar, quitar, sustraer algo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como verbo genérico para nombrar la acción de robar.", example: "Le cató la billetera sin que se diera cuenta." },
  { word: "Cayata", meaning: "Alpargata.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «caminante de tela» y «zafallata».", example: "Andaba en cayatas todo el verano." },
  { word: "Chaffe", meaning: "Vigilante o agente policial.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «chafo» y «botón».", example: "Cruzaron de vereda al ver venir al chaffe." },
  { word: "Chafo", meaning: "Vigilante o agente policial.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «chaffe» y «botón».", example: "El chafo los paró en la esquina para pedirles documentos." },
  { word: "Chambra", meaning: "Silla.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para un mueble de uso cotidiano.", example: "Le acercó una chambra para que se sentara a esperar." },
  { word: "Chamuyar", meaning: "Hablar; en especial, hablar de manera persuasiva para convencer o seducir a alguien.", category: "tango", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con el sentido simple de «hablar». Con el tiempo el uso se fue cargando de un matiz de persuasión o seducción, atribuido por algunos estudiosos al caló, la lengua de los gitanos españoles, donde «chamullar» ya tenía un sentido cercano.", example: "No me chamuyes más, decime la verdad." },
  { word: "Chancleta", meaning: "Puerta.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «virgen».", example: "Forzaron la chancleta del fondo para entrar sin ser vistos." },
  { word: "Chantas", meaning: "Medias, la prenda que se usa en los pies.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para esa prenda. No debe confundirse con «chanta» (tramposo, informal), palabra de origen distinto.", example: "Colgó las chantas mojadas para que se secaran." },
  { word: "China", meaning: "Cortaplumas.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «vaivén de camisulón».", example: "Llevaba siempre una china escondida en el bolsillo." },
  { word: "Chinche", meaning: "Portamonedas de mujer.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario específico de los punguistas.", example: "Le sacó la chinche del bolso sin que se percatara." },
  { word: "Chocolata", meaning: "Sangre.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «colorada».", example: "Quedó con la camisa manchada de chocolata después de la pelea." },
  { word: "Chornar", meaning: "Dormir.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «atorrar» y «polishar».", example: "Se fue a chornar apenas terminó de comer." },
  { word: "Choro", meaning: "Ladrón, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «caco», «ladrillo», «lunfardo», «lunfa» y «malevo». Es una de las voces que más se mantuvo vigente hasta hoy para nombrar a un ladrón.", example: "Un choro le afanó la mochila en el colectivo." },
  { word: "Chuchero", meaning: "Miedoso, cobarde.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «chucho» (miedo).", example: "No seas chuchero y saltá de una vez." },
  { word: "Chucho", meaning: "Miedo. Tener chucho o estar de chucho es tener miedo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, de la que deriva «chuchero» (miedoso).", example: "Le agarró un chucho tremendo cuando escuchó los pasos." },
  { word: "Cieiro", meaning: "Olor.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como voz de uso general en el habla popular de la época.", example: "El cieiro a comida invadía toda la cuadra." },
  { word: "Cola", meaning: "Cadena de reloj. Un bobo sin cola es lo mismo que un bobo garroteado: un reloj sin su cadena.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario específico dedicado al robo de relojes.", example: "Le arrancaron la cola del reloj de un tirón." },
  { word: "Colarse", meaning: "Entrar sin ser visto a una casa o habitación para robar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con el sentido específico de introducirse en una vivienda para cometer un robo.", example: "Se colaron por la ventana mientras la familia dormía." },
  { word: "Colgante", meaning: "Reloj con cadena. Hacer un colgante es robar un reloj junto con su cadena.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario de los ladrones especializados en relojes.", example: "Le hizo un colgante al pasajero distraído del tranvía." },
  { word: "Colorada", meaning: "Sangre.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «chocolata».", example: "Quedó tirado en el piso, cubierto de colorada." },
  { word: "Comprador", meaning: "El que se dedica a comprarles a los ladrones los objetos robados.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Describe una figura clave de la cadena delictiva: el que da salida comercial a la mercadería robada.", example: "Todo lo que afanaban terminaba en manos del mismo comprador." },
  { word: "Conqué", meaning: "Lápiz, lapicera o cualquier instrumento para escribir.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un objeto de uso corriente.", example: "Buscó un conqué para anotar la dirección." },
  { word: "Contar", meaning: "Engañar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, ligada al «trabajo de cuento», la estafa clásica basada en una historia inventada.", example: "Lo contaron con la vieja historia del tío rico." },
  { word: "Correo", meaning: "Papelito pegado en una puerta para saber, sin necesidad de vigilar todo el tiempo, si alguien entró o salió.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro de las técnicas de vigilancia previas al robo que describe el libro.", example: "Puso un correo en la puerta antes de irse a espiar la casa." },
  { word: "Cortante", meaning: "Tijera.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para una herramienta de uso corriente.", example: "Usó el cortante para abrir el paquete." },
  { word: "Corte", meaning: "Cortafierro, herramienta para forzar cerraduras o rejas.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «santo» y «arzobispo».", example: "Entraron con el corte y forzaron la puerta del depósito." },
  { word: "Cuento", meaning: "Historia inventada para engañar a alguien y sacarle dinero. Tomar el cuento es creer en esa historia, como la clásica del legado de un tío rico.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, describiendo una de las estafas más difundidas de la época: el «cuento del tío».", example: "Cayó en el cuento y le dio toda la plata que tenía ahorrada." },
  { word: "Cuervo", meaning: "Sacerdote, capellán de una prisión.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario carcelario del libro.", example: "El cuervo pasaba una vez por semana a hablar con los presos." },
  { word: "Cumple", meaning: "Cómplice.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como acortamiento de «cómplice».", example: "Cayó preso junto con su cumple de siempre." },
  { word: "Dar chinazo", meaning: "Cortar un bolsillo por fuera con un cortaplumas para sacar el dinero de adentro.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del amplio repertorio de técnicas de robo que el libro agrupa bajo el verbo «dar», junto a «dar la biaba» o «dar un calote».", example: "Le dieron chinazo en el colectivo sin que se diera cuenta." },
  { word: "De vado", meaning: "Engañar; se usa en el mismo sentido que «contar».", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, remitida por el propio autor a la voz «contar».", example: "Lo agarraron de vado con el cuento de siempre." },
  { word: "Dejar", meaning: "Depositar algo en un lugar seguro para poder retirarlo más adelante.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con el sentido específico de esconder objetos robados para recuperarlos después.", example: "Dejó el bagayo escondido hasta que se calmaran las cosas." },
  { word: "Derebute", meaning: "Notable, admirable. Misho de rebute significa muy pobre, más pobre que las ratas.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, usada como locución adverbial de énfasis.", example: "Se compró un auto de rebute con la primera changa grande." },
  { word: "Descuido", meaning: "Estar de descuido es hallarse distraído, sin prestar atención.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario que describe el «trabajo de descuido», el robo que aprovecha la distracción de la víctima.", example: "Le afanaron la cartera apenas se puso de descuido." },
  { word: "Desempaquetar", meaning: "Abrir una puerta o desabrochar la ropa de alguien para poder robarle del bolsillo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario específico de los punguistas.", example: "Lo desempaquetó sin que se diera cuenta en medio de la multitud." },
  { word: "Dátil", meaning: "Dedo. Un buen dátil es un punguista hábil.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como metáfora que compara la destreza manual del ladrón de bolsillos con la agilidad de los dedos.", example: "Era conocido como un buen dátil en toda la estación." },
  { word: "Embrocado", meaning: "Visto, reconocido, descubierto.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como participio de «embrocar» (mirar).", example: "Quedó embrocado apenas entró al negocio." },
  { word: "Embrocantes", meaning: "Anteojos.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «embrocar» (mirar).", example: "Se puso los embrocantes para leer el diario." },
  { word: "Embrocar", meaning: "Mirar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «manyar», «campanear» y «jamar».", example: "Lo embrocó de arriba abajo antes de acercarse." },
  { word: "Embroque", meaning: "Mirada.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «embrocar».", example: "Le tiró un embroque que lo dejó helado." },
  { word: "Enajar", meaning: "Huir, salir corriendo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como variante de «najar», voz emparentada con el caló.", example: "Enajaron apenas escucharon el silbato del vigilante." },
  { word: "Enaje", meaning: "Huida, salida repentina. Dar el enaje a una cosa es esconderla.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «enajar».", example: "Se dieron el enaje antes de que llegara la policía." },
  { word: "Encanado", meaning: "Preso, encarcelado.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «estarado», «apanado» y «amurado».", example: "Quedó encanado por seis meses en la comisaría del barrio." },
  { word: "Encanar", meaning: "Aprehender, detener a alguien.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «encanado».", example: "Lo encanaron apenas salió del boliche." },
  { word: "Encapillante", meaning: "Traje completo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para una vestimenta completa.", example: "Se compró un encapillante nuevo para el casamiento." },
  { word: "Endulzante", meaning: "Azúcar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un producto de consumo diario.", example: "Le faltaba endulzante para el café." },
  { word: "Engrupir", meaning: "Distraer o engatusar a alguien.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, emparentada con «grupo» (el compadre o ayudante del ladrón). La palabra se mantiene hoy con el sentido de mentir o hacer creer algo falso.", example: "Lo engrupió con una historia que no tenía ni pies ni cabeza." },
  { word: "Engular", meaning: "Morder.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como voz de uso general en el habla popular de la época.", example: "El perro le engulló la mano al querer acariciarlo." },
  { word: "Ensuciar", meaning: "Sembrar cizaña o enemistad entre dos personas.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, en un sentido figurado distinto del literal.", example: "Alguien los ensució con chismes hasta que dejaron de hablarse." },
  { word: "Entregador", meaning: "La persona que le da al ladrón los datos necesarios para robar a alguien o en una casa, a cambio de una parte del botín.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Describe una figura clave del robo organizado: el informante interno.", example: "El propio sereno era el entregador de la banda." },
  { word: "Esbirro", meaning: "Carcelero, guardián o celador de una prisión.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «verdugo» y «jodido».", example: "El esbirro los hacía formar todas las mañanas en el patio." },
  { word: "Escabiador", meaning: "Bebedor. Un escabiador insigne es un borracho habitual.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «escabiar» (beber).", example: "Era conocido como escabiador insigne en todos los boliches." },
  { word: "Escabiar", meaning: "Beber; también emborracharse.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «escabio» y «escabiador».", example: "Se pusieron a escabiar apenas cobraron." },
  { word: "Escabio", meaning: "Bebida alcohólica en general. El escabio amarillo es coñac, el escabio fuerte aguardiente y el escabio verde ajenjo. Estar escabio es estar ebrio.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con toda una clasificación de bebidas según el color o la graduación.", example: "Trajeron todo tipo de escabio para la fiesta." },
  { word: "Escalineta", meaning: "Cierto tipo de llave usada por los ladrones.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico sobre llaves para forzar cerraduras.", example: "Probó con la escalineta hasta que la cerradura cedió." },
  { word: "Escamoteo", meaning: "Robo que consiste en sustituir un objeto por otro sin que la víctima lo note.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro de la clasificación de tipos de robo que hace el libro, junto al escrusho y la punga.", example: "El trabajo de escamoteo dejaba a la víctima con un paquete vacío." },
  { word: "Escarbadiente", meaning: "Alfiler de corbata.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «espina».", example: "Le robaron el escarbadiente de oro sin que se diera cuenta." },
  { word: "Escolazador", meaning: "Jugador, el que apuesta dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, de la que deriva «escolazar».", example: "Era un escolazador conocido en todas las timbas del barrio." },
  { word: "Escolazar", meaning: "Jugar dinero, apostar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «escolazador».", example: "Se pasó la noche escolazando hasta perder todo lo que tenía." },
  { word: "Escrachador", meaning: "Fotógrafo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, de la que derivan «escrachar» y «escracho».", example: "Fue al escrachador para sacarse la foto del documento." },
  { word: "Escrachar", meaning: "Retratar, fotografiar; también escribir o anotar algo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Con el tiempo, el verbo evolucionó hasta significar exponer públicamente a alguien, sentido que conserva en el español rioplatense actual.", example: "Lo escracharon en las redes por lo que había hecho." },
  { word: "Escrachera", meaning: "Taller fotográfico.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «escracho» (fotografía).", example: "Reveló las fotos en una escrachera del centro." },
  { word: "Escracho", meaning: "Rostro; también una fotografía de una persona o una carta escrita. Un escracho a la gurda es un rostro hermoso, y un escracho fulero, uno feo. Un escracho volante es una careta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es el antecedente directo del actual «escrache», la denuncia pública que expone el rostro y la identidad de alguien.", example: "Tenía un escracho fulero, pero buen corazón." },
  { word: "Escrushante", meaning: "Ladrón especializado en el escrusho, el robo dentro de una casa vacía.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «escrusho» y «escrushar».", example: "El escrushante entraba siempre de día, cuando sabía que la casa estaba vacía." },
  { word: "Escrushar", meaning: "Abrir o forzar una puerta o un mueble para robar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «escrusho» y «escrushante».", example: "Escrusharon la puerta del fondo en cuestión de segundos." },
  { word: "Escrusho", meaning: "Robo cometido dentro de una casa, de día o de noche, cuando no hay nadie adentro.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como una de las categorías de robo que describe el libro.", example: "Le hicieron un escrusho mientras estaba de vacaciones." },
  { word: "Espada", meaning: "Llave, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «yuga» y «sha».", example: "Guardaba todo un manojo de espadas para distintas cerraduras." },
  { word: "Espantarse", meaning: "Mudarse de casa.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con un sentido distinto al de asustarse.", example: "Se espantaron a otro barrio apenas juntaron unos pesos." },
  { word: "Esparo", meaning: "El compadre o ayudante de un punguista, que lo asiste durante el robo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario que describe la organización en pareja del robo de bolsillos.", example: "Iba de esparo mientras el otro le tiraba la punga al otario." },
  { word: "Espiantar", meaning: "Irse, huir.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «espiante». Con el tiempo pasó al habla general como sinónimo de robar o escaparse.", example: "Espiantaron apenas sonó la alarma." },
  { word: "Espiante", meaning: "Huida. El grillo de espiante es el bolsillo trasero del pantalón, tocar la polca del espiante es huir, y dar el espiante a algo es ocultarlo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «espiantar».", example: "Se dieron el espiante antes de que llegara la cana." },
  { word: "Espina", meaning: "Alfiler de corbata.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «escarbadiente».", example: "Llevaba una espina de plata prendida en la corbata." },
  { word: "Esquillar", meaning: "Renegar, rabiar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «estrilar».", example: "Se puso a esquillar apenas se enteró de la noticia." },
  { word: "Estampa", meaning: "El molde o la impresión que se toma de una llave para poder copiarla.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «prueba», dentro del vocabulario técnico de los ladrones especialistas en llaves.", example: "Sacó la estampa de la llave con un poco de cera." },
  { word: "Estaribel", meaning: "Cárcel, prisión.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «estaro». Un estaribel de manyamiento era, según el libro, el depósito policial para los contraventores.", example: "Pasó dos años en el estaribel por aquel asunto." },
  { word: "Estaro", meaning: "Cárcel, prisión. Un estaro chico es una comisaría, un estaro a la gurda es la Penitenciaría, y un estaro de minas es la cárcel de mujeres. Tomar de estaro es aprehender.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con toda una clasificación de tipos de prisión según su gravedad y su población.", example: "Lo llevaron directo al estaro chico de la esquina." },
  { word: "Estazo", meaning: "Ignorante, tonto, infeliz.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como uno de los tantos adjetivos que el libro reserva para nombrar a la víctima fácil de un engaño.", example: "Le hicieron el cuento porque lo vieron cara de estazo." },
  { word: "Estrilador", meaning: "Desconfiado, celoso, de mal carácter.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «estrilar».", example: "Es tan estrilador que no le podés hablar con nadie delante." },
  { word: "Estrilar", meaning: "Renegar; también desconfiar o tener celos.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «estrilador» y «estrilo».", example: "Se pasó toda la noche estrilando por los celos." },
  { word: "Estrilo", meaning: "Rabieta o berrinche; también un hecho delictivo. Tomar un estrilo es renegar o rabiar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, emparentada con «estrilar».", example: "Agarró un estrilo tremendo cuando se enteró de la traición." },
  { word: "Fangos", meaning: "Zapatos, calzado.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «fangushes» y «caminantes».", example: "Se compró unos fangos nuevos para el baile." },
  { word: "Fangushera", meaning: "Zapatería. El bacán de fangushera es el dueño o el zapatero.", category: "cotidiano", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «fangushes» (zapatos).", example: "Llevó los fangos a arreglar a la fangushera de la esquina." },
  { word: "Fangushes", meaning: "Zapatos, calzado.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «fangos» y «caminantes».", example: "Andaba con los fangushes rotos de tanto caminar." },
  { word: "Farinera", meaning: "Daga o cuchillo grande.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un arma blanca de la época.", example: "Sacó la farinera apenas se armó la pelea." },
  { word: "Farra", meaning: "Diversión, jarana, fiesta prolongada.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es una de las voces que se mantuvo intacta hasta hoy en el habla rioplatense.", example: "Se fueron de farra toda la noche y llegaron al amanecer." },
  { word: "Farrear", meaning: "Divertirse, salir de fiesta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «farra».", example: "Todos los sábados salían a farrear por el centro." },
  { word: "Fayuto", meaning: "Falso, de poco valor; también una actitud falsa o hipócrita.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Todavía se usa hoy para describir algo trucho o a alguien poco confiable.", example: "Le vendió un reloj fayuto haciéndolo pasar por original." },
  { word: "Fazo", meaning: "Cigarro, cigarrillo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «fumante».", example: "Le pidió un fazo prestado al que estaba sentado al lado." },
  { word: "Ferros", meaning: "Pesos, dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «mangangás».", example: "No le quedaban ferros ni para el boleto." },
  { word: "Filar", meaning: "Hacer el cuento, es decir, engañar a la víctima en la estafa del legado del tío.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario que describe el «trabajo de otario de cuento».", example: "Le tocaba filar mientras el otro sostenía la historia." },
  { word: "Filo", meaning: "El estafador que le hace el cuento a la víctima.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «filar».", example: "El filo se ganó la confianza del otario en pocos minutos." },
  { word: "Flor", meaning: "Marca que el estafador hace en un naipe para reconocerlo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «floreado» y «florear».", example: "Descubrió la flor en el dorso de la carta y paró el juego." },
  { word: "Floreado", meaning: "Marcado, dicho de un naipe.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, participio de «florear».", example: "Jugaba siempre con un mazo floreado." },
  { word: "Florear", meaning: "Marcar los naipes para reconocerlos y hacer trampa al jugar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario de los tahúres.", example: "Lo pescaron floreando la baraja en pleno juego." },
  { word: "Formar", meaning: "Inventar una historia falsa para engañar a alguien y sacarle dinero.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, ligada directamente al trabajo de cuento.", example: "Le formó una historia tan creíble que le creyó todo." },
  { word: "Francesa", meaning: "Cierto tipo de llave usada por los ladrones.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del extenso vocabulario técnico sobre llaves que recoge el libro.", example: "Probó con la francesa hasta abrir la cerradura vieja." },
  { word: "Fulero", meaning: "Malo, feo, cobarde.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. La palabra se mantiene hoy con el mismo sentido despectivo.", example: "Le hizo un trabajo tan fulero que tuvo que rehacerlo todo." },
  { word: "Fulminante", meaning: "Fósforo. Los fulminantes sordos son los fósforos que no hacen ruido al encenderse.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un objeto de uso corriente, útil también para no ser escuchado durante un robo nocturno.", example: "Encendió el fulminante sordo para no despertar a nadie." },
  { word: "Fumante", meaning: "Cigarro, cigarrillo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «fazo».", example: "Se armó un fumante mientras esperaba el tranvía." },
  { word: "Fumantera", meaning: "Cigarrería.", category: "cotidiano", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «fumante» (cigarrillo).", example: "Compró el tabaco en la fumantera de la esquina." },
  { word: "Fundido", meaning: "Arruinado; el que quedó en una mala situación.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, participio de «fundir». Se mantiene hoy con el sentido de estar en la ruina.", example: "Quedó fundido después de perder todo en la timba." },
  { word: "Fundir", meaning: "Colocar a alguien en una mala situación, generalmente económica.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «hundir».", example: "Ese socio lo terminó de fundir con sus malos manejos." },
  { word: "Funshe", meaning: "Sombrero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para una prenda de vestir.", example: "Se acomodó el funshe antes de salir a la calle." },
  { word: "Funshera", meaning: "Sombrerería.", category: "cotidiano", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «funshe» (sombrero).", example: "Compró un funshe nuevo en la funshera del centro." },
  { word: "Gallina", meaning: "Bailarina.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para una mujer dedicada al baile.", example: "La gallina del cabaret era la más aplaudida de la noche." },
  { word: "Gallo", meaning: "Bailarín.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, forma masculina de «gallina» en este mismo sentido.", example: "Era el mejor gallo del salón para el tango." },
  { word: "Gamba", meaning: "Pierna.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Con el tiempo, «gamba» también pasó a significar cien pesos en el habla popular.", example: "Se lastimó la gamba jugando al fútbol en la plaza." },
  { word: "Gangul", meaning: "Prendedor de mujer.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para una joya de uso femenino, objeto habitual del robo de la época.", example: "Le afanaron el gangul mientras esperaba el tranvía." },
  { word: "Ganso", meaning: "Pene.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como una de las tantas metáforas del habla popular para nombrar el órgano sexual masculino.", example: "Se hacían bromas subidas de tono sobre el ganso en el vestuario." },
  { word: "Garroteado", meaning: "Dicho de un reloj: al que le falta el anillo, porque se lo rompieron para robarlo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, participio de «garrotear».", example: "Encontraron el reloj garroteado tirado en la vereda." },
  { word: "Garrotear", meaning: "Romper con los dedos el anillo de un reloj para poder llevárselo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico de los ladrones de relojes.", example: "Garroteó el reloj en un segundo, sin que la víctima lo notara." },
  { word: "Gil", meaning: "Tonto, fácil de engañar.", category: "tango", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Es una de las voces lunfardas más populares, inmortalizada después por incontables letras de tango.", example: "No seas gil y fijate bien antes de firmar." },
  { word: "Gorra", meaning: "Pene.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como otra de las metáforas del habla popular de la época para el órgano sexual masculino.", example: "Hacían bromas subidas de tono sobre la gorra en el vestuario." },
  { word: "Graja", meaning: "Dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, una más entre las numerosas voces lunfardas que nombraban la plata.", example: "Juntó toda la graja que pudo antes de viajar." },
  { word: "Grillete", meaning: "Bolsillo lateral del pantalón.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario específico de los punguistas.", example: "Le sacó la billetera del grillete sin que se diera cuenta." },
  { word: "Grillo", meaning: "Bolsillo lateral del pantalón. El grillo de espiante es el bolsillo trasero.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «grillete».", example: "Guardaba las llaves en el grillo derecho." },
  { word: "Grupo", meaning: "El compadre o ayudante que asiste a un ladrón durante el robo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. De esta voz deriva «engrupir», que se mantiene vigente con el sentido de mentir o engañar.", example: "Trabajaba siempre con el mismo grupo en los golpes grandes." },
  { word: "Gueyes", meaning: "Piojos.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un parásito habitual en las condiciones de vida precarias de la época.", example: "Se rapó la cabeza para sacarse los gueyes." },
  { word: "Gufalo", meaning: "Extranjero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, en un contexto marcado por la enorme inmigración europea de fines del siglo XIX.", example: "Lo tomaron por gufalo apenas escucharon el acento." },
  { word: "Guiñar", meaning: "Hacer una marca o señal en un naipe para reconocerlo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, emparentada con «florear», dentro del vocabulario de los tahúres tramposos.", example: "Guiñaba la carta con una uña sin que nadie lo notara." },
  { word: "Guita", meaning: "Dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es una de las voces lunfardas para el dinero más usadas hasta hoy en el habla rioplatense.", example: "No le alcanzaba la guita ni para el colectivo." },
  { word: "Guitarra", meaning: "Dinero; también un aparato que simulaba contener monedas, usado en ciertas estafas.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con una doble acepción: la plata en sí y el artefacto que se usaba para simularla en un engaño.", example: "Usó la guitarra para convencerlo de que la máquina hacía plata sola." },
  { word: "Guitero", meaning: "Cobrador.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «guita» (dinero).", example: "El guitero pasaba todos los primeros del mes." },
  { word: "Hacer una burra", meaning: "Robar una caja de caudales.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del extenso repertorio de expresiones con «hacer» que el libro dedica a distintos tipos de robo, como «hacer un colgante» o «hacer una música».", example: "Hicieron una burra en la oficina durante el fin de semana largo." },
  { word: "Hembra", meaning: "En la jerga de los ladrones de llaves, aquella cuya caña es hueca.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro de la clasificación técnica de llaves según la forma de la caña.", example: "Necesitaba una hembra para copiar esa cerradura en particular." },
  { word: "Hoteles", meaning: "Robo cometido mientras la víctima duerme, generalmente en una posada u hotel.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como una de las modalidades del «trabajo» descriptas en el libro.", example: "Le hicieron el trabajo de hoteles mientras dormía después del viaje." },
  { word: "Hueca", meaning: "Cierto tipo de llave, de caña hueca, usada por los ladrones.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico sobre llaves.", example: "Guardaba varias huecas en el fondo del cajón." },
  { word: "Hundido", meaning: "Condenado a prisión por un período largo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, relacionada con «hundir» y «fundir».", example: "Quedó hundido después de aquella condena tan larga." },
  { word: "Hundir", meaning: "Colocar a alguien en una mala situación.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «fundir».", example: "Lo hundió con su propio testimonio ante el juez." },
  { word: "Impase", meaning: "Muerto.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para referirse a una persona fallecida.", example: "Lo dieron por impase apenas encontraron el cuerpo." },
  { word: "Indicador", meaning: "El que aporta datos o informes para facilitar un robo; sinónimo de indique, santero y entregador.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina.", example: "El indicador les avisó cuándo la casa iba a quedar vacía." },
  { word: "Indique", meaning: "El que aporta datos o informes para facilitar un robo; lo mismo que santero, indicador y entregador.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país.", example: "Nadie sospechaba que el sereno era el indique de la banda." },
  { word: "Inglesa", meaning: "Cierto tipo de llave usada por los ladrones.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico sobre llaves.", example: "Con la inglesa abrió la cerradura en segundos." },
  { word: "Ingrediente", meaning: "Tabaco.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un producto de consumo habitual.", example: "Compró un poco de ingrediente para armar un cigarro." },
  { word: "Ir a la gurda con la mina", meaning: "Festejar o pasarla bien con la pareja o compañera.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del amplio repertorio de expresiones con «ir» que recoge el libro.", example: "Se fueron a la gurda con la mina apenas cobró." },
  { word: "Izquierda", meaning: "Cierto tipo de llave usada por los ladrones.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario técnico sobre llaves.", example: "Probó primero con la izquierda antes de forzar la cerradura." },
  { word: "Jaife", meaning: "Hombre elegante y presumido.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «lechuguino».", example: "Se vestía como un jaife aunque no tuviera un peso." },
  { word: "Jamado", meaning: "Comido; también visto o mirado.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, participio de «jamar».", example: "Ya estaba todo jamado cuando llegaron los últimos invitados." },
  { word: "Jamar", meaning: "Comer o mirar; también entender. Jamar el tiempo es observar y tomar informes, y jamar una brema es marcar una baraja.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, con varios sentidos según el contexto.", example: "Se sentaron a jamar apenas llegaron a la fonda." },
  { word: "Jica", meaning: "Alambre.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un material de uso corriente, útil también para forzar cerraduras simples.", example: "Abrió el candado con un pedazo de jica." },
  { word: "Jodido", meaning: "Carcelero, celador o guardián de una prisión.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «esbirro» y «verdugo».", example: "El jodido no dejaba pasar ni una sola falta." },
  { word: "Laborar", meaning: "Trabajar, ejercer una ocupación honesta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, usada por oposición a «trabajar» en el sentido de robar, para distinguir el oficio honrado del delito.", example: "Después de salir del estaro se puso a laborar en una fábrica." },
  { word: "Lache", meaning: "Casa de empeño o montepío.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para el cambalache o casa de empeños.", example: "Empeñó el reloj en el lache de la esquina." },
  { word: "Ladrillo", meaning: "Ladrón, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «caco», «choro», «lunfardo», «lunfa» y «malevo».", example: "Toda la cuadra sabía que era un ladrillo de cuidado." },
  { word: "Lamentarse", meaning: "Requebrar, hacer el amor con palabras.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, con un sentido de cortejo amoroso distinto al literal de quejarse.", example: "Se pasó toda la noche lamentándose con la moza del boliche." },
  { word: "Largar", meaning: "Dar, regalar algo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con un sentido más amplio del habitual de soltar o abandonar.", example: "Le largó unos pesos para que se tomara el colectivo." },
  { word: "León", meaning: "Pantalón.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para una prenda de vestir.", example: "Le robaron la billetera del bolsillo del león." },
  { word: "Lengo", meaning: "Pañuelo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un objeto de uso corriente.", example: "Se secó la frente con el lengo antes de entrar." },
  { word: "Lienzo", meaning: "Sábana.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para una prenda de cama.", example: "Colgó el lienzo a secar en el patio." },
  { word: "Lima", meaning: "Camisa o camiseta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para una prenda de vestir.", example: "Se cambió la lima antes de salir a la calle." },
  { word: "Llorar", meaning: "Requebrar, hacer el amor con palabras.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «lamentarse» en este mismo sentido de cortejo.", example: "Le lloraba a la vecina todas las tardes desde la vereda." },
  { word: "Loca", meaning: "Prostituta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario que el libro dedica al mundo de la prostitución porteña de la época.", example: "La conocían como la loca de la esquina del boliche." },
  { word: "Lora", meaning: "Mujer, querida.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como una de las tantas voces para nombrar a la mujer o la pareja.", example: "Salió a pasear con la lora por el centro." },
  { word: "Lunfa", meaning: "Abreviatura de lunfardo: ladrón.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como forma corta de «lunfardo».", example: "Le decían el lunfa desde chico por sus mañas." },
  { word: "Lunfardo", meaning: "Ladrón, en general; también el idioma que hablaban los delincuentes en Buenos Aires.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, que le da nombre y estudio sistemático por primera vez a esta jerga. Con el tiempo, «lunfardo» dejó de nombrar al ladrón y pasó a designar exclusivamente el habla popular rioplatense, su sentido actual.", example: "El lunfardo terminó siendo la palabra que le dio nombre a todo este diccionario." },
  { word: "Lusante", meaning: "Farol.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un objeto de iluminación pública.", example: "Se escondió detrás del lusante para no ser visto." },
  { word: "Machete", meaning: "Pene.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como otra de las metáforas del habla popular para el órgano sexual masculino.", example: "Hacían bromas subidas de tono sobre el machete en el vestuario." },
  { word: "Machetear", meaning: "Fornicar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «machete» en el sentido sexual.", example: "Se jactaba de haber machetado con media cuadra." },
  { word: "Macho", meaning: "En la jerga de los ladrones de llaves, aquella cuya caña es maciza.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro de la clasificación técnica de llaves, en oposición a «hembra» (caña hueca).", example: "Necesitaba un macho para esa cerradura antigua." },
  { word: "Magura", meaning: "Bueno, excelente.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como adjetivo de elogio dentro del habla de la época.", example: "El asado le quedó magura, todos repitieron." },
  { word: "Malevo", meaning: "Ladrón, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «caco», «choro» y «ladrillo». Con el tiempo, el término derivó hacia el sentido de hombre pendenciero o guapo de barrio, que el tango popularizó.", example: "Se paseaba con pinta de malevo por el barrio." },
  { word: "Mancada", meaning: "Error, golpe en falso; un robo que fue descubierto.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «mancado» y «mancar».", example: "Fue una mancada quedarse tanto tiempo dentro de la casa." },
  { word: "Mancado", meaning: "Descubierto, sorprendido en el momento del robo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, participio de «mancar».", example: "Quedó mancado justo cuando salía por la ventana." },
  { word: "Mancar", meaning: "Descubrir o sorprender a un ladrón en el momento del robo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «mancada» y «mancado».", example: "El sereno lo mancó justo cuando forzaba la puerta." },
  { word: "Mandil", meaning: "Servilleta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un objeto de mesa de uso corriente.", example: "Se limpió las manos con el mandil antes de levantarse." },
  { word: "Mangangás", meaning: "Pesos, dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «ferros».", example: "Juntó los mangangás justos para pagar el alquiler." },
  { word: "Manojo", meaning: "Atado de llaves unidas por los aros.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario técnico de los especialistas en llaves.", example: "Llevaba un manojo entero de llaves para probar en la cerradura." },
  { word: "Manrocas", meaning: "Vestido completo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para el conjunto de la vestimenta.", example: "Se compró unas manrocas nuevas para la fiesta." },
  { word: "Manyado", meaning: "Visto, reconocido; descubierto en el momento de cometer un robo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, participio de «manyar».", example: "Quedó manyado apenas metió la mano en el bolsillo ajeno." },
  { word: "Manyamiento", meaning: "Reconocimiento policial de delincuentes.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «manyar» (reconocer).", example: "Lo llevaron al manyamiento después de la detención." },
  { word: "Manyar", meaning: "Comer o mirar; también reconocer o entender algo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Es una de las voces lunfardas más difundidas, todavía vigente con el sentido de entender o darse cuenta de algo.", example: "¿Manyás lo que te estoy diciendo?" },
  { word: "Marca", meaning: "Cicatriz.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «marcar».", example: "Tenía una marca en la cara desde la pelea de aquella noche." },
  { word: "Marcar", meaning: "Herir con un arma de filo con la intención de dejar una cicatriz.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario de la violencia entre bandas que describe el libro.", example: "Lo marcaron en la cara como advertencia." },
  { word: "Marica", meaning: "Lata de aceite.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para un envase de uso corriente en la época.", example: "Guardaba el aceite en una marica en el fondo de la cocina." },
  { word: "Marroca", meaning: "Cadena de reloj.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «brija» y «traya».", example: "Le arrancó la marroca sin que se diera cuenta." },
  { word: "Marroque", meaning: "Pan.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, de la que deriva «marroquera».", example: "Compró un marroque fresco para el desayuno." },
  { word: "Marroquera", meaning: "Panadería.", category: "cotidiano", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «marroque» (pan).", example: "Pasó por la marroquera antes de ir al trabajo." },
  { word: "Masa", meaning: "Sustancia usada para sacar el molde de una llave; lo mismo que pastilla.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico de los especialistas en copiar llaves.", example: "Usó la masa para sacar la estampa de la llave." },
  { word: "Mayorengo", meaning: "Oficial de policía o autoridad judicial, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país.", example: "El mayorengo llegó a hacer las preguntas de rutina." },
  { word: "Mayorenguera", meaning: "Comisaría.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «mayorengo».", example: "Lo llevaron directo a la mayorenguera del barrio." },
  { word: "Media luna", meaning: "Bolsillo exterior del saco, usado para guardar el pañuelo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario específico de los punguistas.", example: "Guardaba el reloj en la media luna del saco." },
  { word: "Medio sardo", meaning: "Cabo de vigilantes.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro de la jerarquía policial que describe el libro, junto a «sardo» (sargento) y «sario» (comisario).", example: "El medio sardo pasó lista antes del cambio de turno." },
  { word: "Merlo", meaning: "Tonto, infeliz, fácil de engañar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, uno de los tantos apodos que el libro reserva para la víctima ingenua de una estafa.", example: "Le hicieron el cuento porque lo vieron cara de merlo." },
  { word: "Mina", meaning: "Mujer, en general; también la pareja o querida de alguien. Una mina de tambo es una prostituta.", category: "tango", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es una de las voces lunfardas más difundidas y sigue siendo, hoy, la forma más común de nombrar a una mujer en el habla coloquial rioplatense.", example: "Se fue caminando con la mina hasta la esquina." },
  { word: "Mino", meaning: "El que ejerce el rol pasivo en una relación homosexual, en el vocabulario de la época; también amante.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario que el libro dedica a los roles y relaciones del ambiente carcelario y delictivo del siglo XIX.", example: "Era conocido como el mino de uno de los presos más viejos." },
  { word: "Misho", meaning: "Pobre. Misho de rebute es muy pobre, y misho de uniforme es estar desnudo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina.", example: "Andaba misho después de perder todo en la timba." },
  { word: "Misiringanga", meaning: "Hombre de raza negra.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «tío misiringanga».", example: "El misiringanga del barrio era el mejor tocando el tambor." },
  { word: "Mistongo", meaning: "Pobre, de poco valor; también falso.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Todavía se usa hoy para nombrar algo humilde o de poco valor.", example: "Vivía en una pieza mistonga al fondo del conventillo." },
  { word: "Mora", meaning: "Bala, proyectil de arma de fuego.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para munición.", example: "Le quedó una mora alojada en la pierna." },
  { word: "Morfar", meaning: "Comer.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es una de las voces lunfardas más difundidas y todavía hoy es sinónimo cotidiano de comer.", example: "Se sentaron a morfar apenas llegaron a la casa." },
  { word: "Morfe", meaning: "Comida.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «morfar».", example: "Llegó justo a tiempo para el morfe." },
  { word: "Morfil", meaning: "Tortilla.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, emparentada con «morfar» (comer).", example: "Hizo un morfil con lo poco que había en la heladera." },
  { word: "Mosqueta", meaning: "Juego de naipes usado para estafar a la víctima.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, una de las estafas clásicas descriptas junto al trabajo de cuento.", example: "Cayó en la mosqueta y perdió toda la plata del sueldo." },
  { word: "Mosquetero", meaning: "El que se vale del juego de la mosqueta para estafar a la víctima.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «mosqueta».", example: "El mosquetero armaba su mesita en la vereda de la estación." },
  { word: "Música", meaning: "Cartera usada para guardar el dinero.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario específico de los punguistas. «Hacer una música» era robar una cartera.", example: "Le hicieron la música en medio de la multitud." },
  { word: "No jamar", meaning: "No entender algo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, forma negativa de «jamar» en el sentido de entender.", example: "No jamaba nada de lo que le estaban explicando." },
  { word: "Orto", meaning: "Ano.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Es una de las voces que más se conserva hoy en el habla coloquial rioplatense, sobre todo en expresiones de mala suerte o fastidio.", example: "Tuvo una mala racha bárbara, de orto total." },
  { word: "Otario", meaning: "Hombre honrado; también ignorante o infeliz, fácil de engañar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es una de las voces centrales del libro: nombra a la víctima de las estafas del cuento y sigue vigente hoy con el mismo sentido.", example: "No seas otario y fijate bien antes de firmar nada." },
  { word: "Paco", meaning: "Dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, una más entre las numerosas voces lunfardas para la plata.", example: "No le quedaba ni un paco para el boleto." },
  { word: "Paleta", meaning: "En la jerga de los ladrones de llaves, la pieza de la llave con forma de banderola.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico sobre las partes de una llave.", example: "La paleta de esa llave estaba gastada de tanto uso." },
  { word: "Pampa", meaning: "Extracto de lotería falsificado, usado para estafar a la víctima.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario que describe las estafas con billetes de lotería, como el tocomocho.", example: "Le mostró la pampa haciéndole creer que había ganado." },
  { word: "Panadera", meaning: "Comisaría.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «sara» y «mayorenguera».", example: "Pasó la noche en la panadera después del escándalo." },
  { word: "Parlo", meaning: "Reloj.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «bobo» dentro del vocabulario de los ladrones de relojes.", example: "Le afanaron el parlo apenas se distrajo." },
  { word: "Parón", meaning: "Dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, una más entre las numerosas voces para la plata.", example: "Juntaron el parón necesario para el pasaje." },
  { word: "Pasadura", meaning: "El hecho de excederse en palabras o en acciones.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «pasarse».", example: "Lo que dijo fue una pasadura que nadie le perdonó." },
  { word: "Pasarse", meaning: "Propasarse, excederse en palabras o en acciones.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, de la que deriva «pasadura».", example: "Se pasó con los comentarios y terminó pidiendo disculpas." },
  { word: "Pastilla", meaning: "Sustancia usada para sacar el molde de una llave; lo mismo que masa.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario técnico de los especialistas en copiar llaves.", example: "Marcó la llave en la pastilla antes de devolvérsela al dueño." },
  { word: "Pertrecho", meaning: "Sartén.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para un utensilio de cocina.", example: "Calentó el aceite en el pertrecho antes de freír." },
  { word: "Pescado", meaning: "Agente de pesquisas.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «tira».", example: "Un pescado vestido de civil los venía siguiendo hacía rato." },
  { word: "Pigrisia", meaning: "Pereza.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como voz de uso general en el habla popular de la época.", example: "Le agarró una pigrisia tremenda y no hizo nada en todo el día." },
  { word: "Pilcha", meaning: "Manta. Una pilcha de atorrar es una frazada.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Con el tiempo, «pilcha» amplió su sentido y hoy nombra, en general, la ropa que alguien usa.", example: "Se tapó con la pilcha para pasar la noche en el atorradero." },
  { word: "Piña", meaning: "Puñetazo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Se mantiene vigente hoy con el mismo sentido en el habla coloquial.", example: "Le metió una piña que lo tiró al piso." },
  { word: "Pisante", meaning: "Pie.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «canoa».", example: "Tenía los pisantes destrozados después de la caminata." },
  { word: "Pájaro cantador", meaning: "Oro.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, una de las metáforas más poéticas del libro para nombrar el metal precioso, mencionada también en la entrada de «amarillo».", example: "Todo lo que llevaba puesto era pájaro cantador." },
  { word: "Poliso", meaning: "Lecho, cama.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un mueble de uso cotidiano.", example: "Se tiró en el poliso apenas llegó de trabajar." },
  { word: "Poroto", meaning: "Brillante, piedra preciosa.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, con un sentido distinto al que tomó después la palabra en el habla popular (el frijol, o una persona o resultado valioso).", example: "Llevaba un poroto enorme en el anillo." },
  { word: "Potrillo", meaning: "Catre.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para un mueble de uso cotidiano.", example: "Durmió esa noche en un potrillo prestado." },
  { word: "Ppira", meaning: "Cartera.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario específico de los punguistas, como sinónimo de «música» y «viuda».", example: "Le vació la ppira sin que se diera cuenta en el tumulto." },
  { word: "Prueba", meaning: "El molde o la impresión que se toma de una llave para poder copiarla.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «estampa».", example: "Sacó la prueba de la llave antes de devolverla al dueño." },
  { word: "Púa", meaning: "Puñalada.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario de la violencia con armas blancas que describe el libro.", example: "Le dieron una púa en la pelea de la esquina." },
  { word: "Pulenta", meaning: "Oro; también dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, mencionada también en la entrada de «amarillo» como una de las metáforas del oro.", example: "Todo lo que llevaba encima era pulenta pura." },
  { word: "Pulisa", meaning: "Cama.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, emparentada con «poliso» y «pulishar».", example: "Se acostó en la pulisa apenas terminó de comer." },
  { word: "Pulishar", meaning: "Dormir.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «atorrar» y «chornar».", example: "Se fue a pulishar apenas terminó el turno." },
  { word: "Punga", meaning: "Sustracción de objetos de los bolsillos de las personas.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Es una de las voces lunfardas más difundidas, todavía vigente para nombrar el robo de bolsillo.", example: "Le hicieron la punga en el subte sin que se diera cuenta." },
  { word: "Punguista", meaning: "Ladrón que sustrae, con astucia y disimulo, objetos de los bolsillos de la gente.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «punga».", example: "El punguista actuaba siempre en las horas pico del subte." },
  { word: "Quibebe", meaning: "Prostíbulo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «tambo».", example: "El quibebe quedaba a pocas cuadras de la comisaría." },
  { word: "Quillete", meaning: "Menor, muchacho.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «vive» y «pebete».", example: "El quillete hacía de campana mientras los grandes robaban." },
  { word: "Quinini", meaning: "Yerba mate.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para un producto de consumo diario.", example: "Compró un paquete de quinini para el mate de la tarde." },
  { word: "Quinta", meaning: "La Penitenciaría de la Capital.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «estaro a la gurda».", example: "Lo trasladaron a la quinta después de la condena." },
  { word: "Raguñear", meaning: "Tener hambre; lo mismo que morfar y bullonar en ese sentido.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, de la que deriva «ragut» (hambre).", example: "Empezó a raguñear apenas pasado el mediodía." },
  { word: "Ragut", meaning: "Hambre.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «raguñear».", example: "Tenía un ragut bárbaro después de tanto caminar." },
  { word: "Reducir", meaning: "Vender objetos, generalmente robados.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. La expresión «reducidor de objetos robados» sigue usándose hoy en el lenguaje judicial y policial.", example: "Reducía todo lo que afanaba a través de un comprador de confianza." },
  { word: "Refilar", meaning: "Dar, pasar o regalar algo. Refilar vento al mayorengo es sobornar a la autoridad.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país.", example: "Le refiló unos pesos al policía para que no dijera nada." },
  { word: "Reo", meaning: "Vago, haragán; lo mismo que atorrante.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Con el tiempo, «reo» amplió su uso hasta describir también lo pintoresco o castizo del habla popular.", example: "Vivía la vida reo, sin apuro y sin horarios." },
  { word: "Reventar", meaning: "Robar, estafar a alguien.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de afanar dentro del vocabulario general del robo.", example: "Lo reventaron apenas bajó del tren." },
  { word: "Rolar", meaning: "Andar en compañía de alguien, ser su amigo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina.", example: "Hacía años que rolaba con la misma barra del barrio." },
  { word: "Rollo", meaning: "Dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, una más entre las numerosas voces lunfardas para la plata.", example: "Se guardó todo el rollo en el bolsillo interior." },
  { word: "Rostrazo", meaning: "La acción de rostrear: quedarse con una parte del robo que no corresponde.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «rostrear».", example: "El rostrazo que le hizo a sus cómplices le costó la confianza de la banda." },
  { word: "Rostrear", meaning: "Ocultarles a los cómplices una parte del botín para quedarse con más de lo que corresponde.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del código de reparto entre ladrones que describe el libro.", example: "Lo descubrieron rostreando y no volvieron a trabajar con él." },
  { word: "Rozado", meaning: "Tanteado; dicho de un bolsillo del que ya se sabe dónde guarda el dinero su dueño.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, participio de «rozar».", example: "El bolsillo ya estaba rozado antes de ejecutar la punga." },
  { word: "Rozar", meaning: "Tantear con disimulo en qué bolsillo guarda alguien el dinero, para poder robárselo después.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario técnico de los punguistas.", example: "Lo rozó en el colectivo antes de decidirse a tirar la punga." },
  { word: "Rufino", meaning: "Rufián, portero de una casa de prostitución.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario que el libro dedica al mundo de la prostitución porteña de la época.", example: "El rufino controlaba la entrada del quibebe." },
  { word: "Sable", meaning: "Pasador de una puerta.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario técnico sobre puertas y cerraduras.", example: "Corrió el sable con cuidado para no hacer ruido." },
  { word: "Sada", meaning: "Posada, casa de hospedaje nocturno.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina.", example: "Pasaron la noche en una sada cerca de la estación." },
  { word: "San Roque", meaning: "Perro.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, en alusión al santo tradicionalmente representado junto a un perro.", example: "El san Roque de la esquina ladraba cada vez que alguien se acercaba." },
  { word: "Santabomba", meaning: "Hombre grueso.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como apodo descriptivo de la contextura física.", example: "El santabomba del boliche siempre pedía dos porciones." },
  { word: "Santera", meaning: "Ferretería.", category: "cotidiano", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, emparentada con «santo» (cortafierro), la herramienta que se conseguía o afilaba allí.", example: "Compró el candado en la santera de la esquina." },
  { word: "Santo", meaning: "Cortafierro, herramienta para forzar cerraduras o rejas.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «corte» y «arzobispo».", example: "Forzaron la reja con el santo en menos de un minuto." },
  { word: "Sara", meaning: "Comisaría.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «panadera» y «mayorenguera».", example: "Lo llevaron a la sara para tomarle declaración." },
  { word: "Sardo", meaning: "Sargento de vigilantes.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro de la jerarquía policial que describe el libro.", example: "El sardo ordenó el operativo en la esquina." },
  { word: "Sario", meaning: "Comisario de policía.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como acortamiento de «comisario», dentro de la jerarquía policial del libro.", example: "El sario en persona vino a supervisar la detención." },
  { word: "Serante", meaning: "Cortaplumas.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «china».", example: "Llevaba un serante escondido en el bolsillo del chaleco." },
  { word: "Servicio", meaning: "Hombre. Un servicio lila es un tonto o infeliz.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país.", example: "Ese servicio lila cayó en el cuento apenas se lo contaron." },
  { word: "Sha", meaning: "Llave, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «espada» y «yuga».", example: "Probó con varias shas hasta encontrar la que servía." },
  { word: "Shacador", meaning: "El que consigue algo valiéndose del engaño.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «shacar».", example: "El shacador se ganó su confianza antes de estafarlo." },
  { word: "Shacamento", meaning: "Engaño, estafa.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «shacar» y «shacador».", example: "Todo el negocio resultó ser un shacamento de punta a punta." },
  { word: "Shacar", meaning: "Engañar, sacarle algo a alguien por medio de la mentira. Una mina sin shacar es una mujer virgen.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país.", example: "Lo shacaron con la vieja historia del terreno en venta." },
  { word: "Sánchez", meaning: "Tonto, infeliz, poco avispado.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, uno de los tantos apodos que el libro reserva para la víctima fácil de un engaño.", example: "Le hicieron el cuento porque lo vieron cara de sánchez." },
  { word: "Sonda", meaning: "El palito que se usa para sondear una cerradura.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario técnico de los ladrones especializados en puertas.", example: "Usó la sonda para averiguar si había alguien adentro." },
  { word: "Sondear", meaning: "Introducir un palito en la cerradura de una puerta para saber si la llave está puesta por dentro.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «sonda».", example: "Sondeó la puerta antes de decidirse a entrar." },
  { word: "Sotala", meaning: "Bolsillo interior del saco, la levita o cualquier prenda similar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario específico de los punguistas.", example: "Guardaba la billetera en la sotala para que no se la afanaran." },
  { word: "Sotana", meaning: "Bolsillo interior del saco; lo mismo que sotala.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como variante de «sotala».", example: "Le sacó el reloj de la sotana sin que se diera cuenta." },
  { word: "Tablero", meaning: "La parte de una puerta que forma un marco o recuadro.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario técnico sobre puertas que describe el «trabajo de tablero», el robo mediante un agujero hecho en ese sector.", example: "Le hicieron un agujero en el tablero para correr el pasador desde afuera." },
  { word: "Tambo", meaning: "Prostíbulo. Una mina de tambo es una prostituta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario que el libro dedica al mundo de la prostitución porteña de fines del siglo XIX.", example: "El tambo funcionaba a pocas cuadras de la comisaría." },
  { word: "Testa", meaning: "Cabeza.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «testamento» en este mismo sentido.", example: "Se golpeó la testa contra el marco de la puerta." },
  { word: "Testamento", meaning: "Cabeza.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo humorístico de «testa».", example: "Le dolía el testamento después de tanto pensar." },
  { word: "Timba", meaning: "Casa de juego.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Es una de las voces lunfardas que más se conserva hoy para nombrar tanto el local como la partida de juego.", example: "Perdió todo lo que tenía en la timba de la esquina." },
  { word: "Timbear", meaning: "Jugar dinero, apostar.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, raíz de «timba» y «timbero».", example: "Se pasaba las noches timbeando en vez de trabajar." },
  { word: "Timbero", meaning: "Jugador, el que apuesta dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «escolazador».", example: "Era un timbero conocido en todas las mesas del barrio." },
  { word: "Tío misiringanga", meaning: "Hombre de raza negra.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «misiringanga».", example: "El tío misiringanga tocaba el tambor mejor que nadie en el barrio." },
  { word: "Tira", meaning: "Agente de pesquisas.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «pescado». Sigue vigente hoy en el habla coloquial para nombrar a un policía de civil.", example: "Un tira los venía siguiendo desde la estación." },
  { word: "Tirar la punga", meaning: "Efectuar la sustracción de un objeto del bolsillo de alguien.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del vocabulario técnico de los punguistas.", example: "Le tiró la punga justo cuando el colectivo frenó de golpe." },
  { word: "Toco", meaning: "La parte o porción que corresponde a cada uno de lo robado.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Dar el toco era entregar la parte correspondiente del botín.", example: "Le dieron su toco apenas repartieron lo robado." },
  { word: "Tocomochero", meaning: "El que practica la estafa del tocomocho: vender un billete de lotería falso haciéndolo pasar por premiado.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, derivada de «tocomocho».", example: "El tocomochero eligió a un turista distraído para su próxima víctima." },
  { word: "Tocomocho", meaning: "Billete de lotería, aparentemente premiado, que se usa para estafar a la víctima.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, una de las estafas clásicas descriptas junto al cuento y la mosqueta.", example: "Le vendieron un tocomocho haciéndole creer que había ganado la lotería." },
  { word: "Tomar de otario", meaning: "Creer que alguien es tonto o fácil de engañar.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, dentro del amplio repertorio de expresiones con «tomar», junto a «tomar de estaro» (aprehender) y «tomar el cuento» (creer una historia inventada).", example: "Lo tomaron de otario y le vaciaron los bolsillos." },
  { word: "Toquero", meaning: "El que sigue a los ladrones haciéndose útil para poder participar de lo robado.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «toco» (la porción del botín).", example: "El toquero siempre andaba cerca de la banda esperando su parte." },
  { word: "Trabajar", meaning: "Robar, en el sentido más amplio de la palabra.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, en oposición directa a «laborar» (trabajar honestamente).", example: "Esa noche decidieron trabajar en el barrio norte." },
  { word: "Trabajo", meaning: "Robo, en general. El libro distingue muchas variantes según el método: de biaba (asalto), de cuento (estafa con una historia falsa), de escrusho (casa vacía), de punga (bolsillos), de tocomocho (billete falso), entre otras.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, que dedica a esta voz una de sus entradas más extensas, clasificando con detalle los distintos tipos de robo y estafa de la época.", example: "Se especializaba en el trabajo de escrusho, siempre de día y sin sorpresas." },
  { word: "Traya", meaning: "Cadena de reloj.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «brija» y «marroca».", example: "Le arrancó la traya de un tirón antes de salir corriendo." },
  { word: "Tumba", meaning: "Puchero, carne cocida en agua.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, con un sentido gastronómico muy distinto al que después tomaría la palabra en la jerga carcelaria moderna, donde «tumba» pasó a nombrar la cárcel.", example: "Comieron una tumba bien caliente esa noche de invierno." },
  { word: "Turro", meaning: "Tonto, haragán.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Sigue usándose hoy, aunque con un matiz más cercano a «traidor» o «mala persona».", example: "No seas turro y devolvele lo que le afanaste." },
  { word: "Vaga", meaning: "Prostituta.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, dentro del vocabulario que el libro dedica al mundo de la prostitución porteña de la época.", example: "La vaga esperaba clientes en la puerta del tambo." },
  { word: "Vaivén", meaning: "Arma blanca, en general. Un vaivén de camisulón es una navaja o cortaplumas, un vaivén corto es una daga, y un vaivén largo a la gurda es un facón, estoque o machete.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, con toda una clasificación de armas blancas según su tamaño.", example: "Sacó el vaivén apenas se armó la discusión." },
  { word: "Vento", meaning: "Dinero.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país. Sigue usándose hoy como una de las voces lunfardas clásicas para la plata.", example: "Le refiló un poco de vento al mayorengo para que no dijera nada." },
  { word: "Verde", meaning: "Yerba mate; también el ajenjo, una bebida alcohólica.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, con dos sentidos según el género de la palabra.", example: "Compró un poco de verde para cebar unos mates." },
  { word: "Verdugo", meaning: "Carcelero, guardián o celador de una prisión.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «esbirro» y «jodido».", example: "El verdugo hacía la ronda cada dos horas por el pabellón." },
  { word: "Vianda", meaning: "Piedra.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga distinto al sentido actual de comida para llevar.", example: "Le tiró una vianda a la ventana para llamar su atención." },
  { word: "Vichenzo", meaning: "Infeliz, corto de alcances.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, uno de los tantos apodos que el libro reserva para la víctima ingenua de un engaño.", example: "Le hicieron el cuento porque lo vieron cara de vichenzo." },
  { word: "Vidrioso", meaning: "Ojo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como metáfora que compara el brillo del ojo con el vidrio.", example: "Tenía el vidrioso hinchado después del golpe." },
  { word: "Virgen", meaning: "Puerta.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «chancleta».", example: "Forzaron la virgen del fondo para entrar sin ser vistos." },
  { word: "Viuda", meaning: "Cartera.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «música» y «ppira».", example: "Le afanaron la viuda en medio de la multitud." },
  { word: "Vive", meaning: "Chicuelo, muchacho.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como sinónimo de «quillete» y «pebete».", example: "El vive hacía de campana mientras los grandes trabajaban." },
  { word: "Yacumina", meaning: "Levita.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como nombre en jerga para una prenda de vestir formal.", example: "Se puso la yacumina para ir al casamiento." },
  { word: "Yin", meaning: "Ginebra.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para una bebida de consumo habitual.", example: "Pidió un yin para entrar en calor." },
  { word: "Yira", meaning: "Vuelta, paseo. Antes se llamaba así también a la ronda obligatoria que debían hacer los ladrones reincidentes por todas las comisarías de la Capital.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina. Con el tiempo, «yira» derivó hacia el sentido de mujer que ejerce la prostitución callejera, muy usado en el tango.", example: "Se fue a dar una yira por el centro antes de volver a casa." },
  { word: "Yirar", meaning: "Pasear, caminar, vagar sin rumbo fijo.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, raíz de «yira».", example: "Se pasaron la tarde yirando por el centro sin comprar nada." },
  { word: "Yuga", meaning: "Llave, en general.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «espada» y «sha».", example: "Guardaba todas las yugas en un manojo aparte." },
  { word: "Yugadera", meaning: "Cerradura.", category: "tumbero", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, derivada de «yuga» (llave).", example: "Forzó la yugadera con una llave falsa." },
  { word: "Zafallata", meaning: "Alpargata.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en la Argentina, como sinónimo de «cayata» y «caminante de tela».", example: "Andaba en zafallatas todo el verano." },
  { word: "Zarzo", meaning: "Anillo.", category: "bajofondo", origin: "Documentada desde 1894 en «El idioma del delito» de Antonio Dellepiane, el primer diccionario de lunfardo publicado en el país, como nombre en jerga para una joya de uso corriente.", example: "Le afanaron el zarzo mientras dormía en el tren." },
];
